{"function":"() => {
const out = {};
const pp = document.querySelectorAll('.primary-pastel-01');
out.pastel = [...pp].map(e=>({tag:e.tagName, cls:e.className, txt:e.textContent.trim().slice(0,60), html:e.outerHTML.slice(0,300)}));
const chips = [...document.querySelectorAll('[class*="cursor"], .cursor-pointer')].slice(0,10).map(e=>e.outerHTML.slice(0,200));
out.chips = chips;
// filter elements
const cidade = [...document.querySelectorAll('*')].filter(e=>e.childElementCount===0 && e.textContent.trim()==='Cidade');
out.cidade = cidade.map(e=>{let p=e.parentElement; return {html:p.outerHTML.slice(0,500), tabindex:p.tabIndex, role:p.getAttribute('role'), pp: p.parentElement.outerHTML.slice(0,300)}});
out.h = [...document.querySelectorAll('h1,h2,h3,h4,h5,h6,[role=heading]')].map(e=>e.tagName+':'+e.textContent.trim().slice(0,40));
out.dateInputs = [...document.querySelectorAll('br-input')].map(e=>({html:e.outerHTML.slice(0,300), inner: e.shadowRoot? e.shadowRoot.innerHTML.slice(0,600):null}));
return out;
}"}

