const act = document.querySelector('tbody tr:nth-child(1) td:nth-child(9)');
out.actions = act.outerHTML.replace(/_ngcontent-[a-z0-9-]+=""/g,'').slice(0,2500);
const hdr = document.querySelector('header');
out.header = hdr ? hdr.outerHTML.replace(/_ngcontent-[a-z0-9-]+=""/g,'').slice(0,2000) : null;
